using System.Text;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.Text;

namespace HomeBuild.Generators;

[Generator(LanguageNames.CSharp)]
public sealed class StronglyTypedIdGenerator : IIncrementalGenerator
{
    private const string AttributeName = "HomeBuild.StronglyTypedIdAttribute";

    private const string AttributeSource = """
        // <auto-generated/>
        namespace HomeBuild;

        [global::System.AttributeUsage(global::System.AttributeTargets.Struct, Inherited = false)]
        internal sealed class StronglyTypedIdAttribute : global::System.Attribute
        {
        }
        """;

    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        context.RegisterPostInitializationOutput(static ctx =>
            ctx.AddSource("StronglyTypedIdAttribute.g.cs", SourceText.From(AttributeSource, Encoding.UTF8)));

        var ids = context.SyntaxProvider.ForAttributeWithMetadataName(
            AttributeName,
            static (node, _) => true,
            static (ctx, _) => new IdModel(
                ctx.TargetSymbol.ContainingNamespace.IsGlobalNamespace ? "" : ctx.TargetSymbol.ContainingNamespace.ToDisplayString(),
                ctx.TargetSymbol.Name));

        context.RegisterSourceOutput(ids, static (spc, id) =>
            spc.AddSource($"{id.Name}.g.cs", SourceText.From(Render(id), Encoding.UTF8)));
    }

    private static string Render(IdModel id)
    {
        var ns = id.Namespace.Length == 0 ? "" : $"namespace {id.Namespace};";
        return $$"""
            // <auto-generated/>
            #nullable enable
            {{ns}}

            [global::System.Diagnostics.DebuggerDisplay("{Value}")]
            partial record struct {{id.Name}}(global::System.Guid Value)
            {
                public static {{id.Name}} New() => new(global::System.Guid.CreateVersion7());

                public override string ToString() => Value.ToString();

                public static bool TryParse(string? text, out {{id.Name}} result)
                {
                    if (global::System.Guid.TryParse(text, out var value))
                    {
                        result = new(value);
                        return true;
                    }

                    result = default;
                    return false;
                }
            }
            """;
    }

    private readonly record struct IdModel(string Namespace, string Name);
}
